        self._price = price

    @property
    def price(self):
        return self._price

class Product:
    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, val):
        if val < 0:
            raise ValueError()
        self._price = val

class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

