def logger(func):
    def wrapper(*args, **kwargs):
        print("Executing...")
        return func(*args, **kwargs)
    return wrapper

from functools import wraps

def my_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def repeat(num_times):
    def decorator_out(func):
        def wrapper(*args, **kwargs):
            for _ in range(num_times):
                func(*args, **kwargs)
        return wrapper
    return decorator_out

def count_up(start=0):
    while True:
        yield start
        start += 1

def inner():
    yield 1
    yield 2

def outer():
    yield from inner()
    yield 3

def accumulator():
    total = 0
    while True:
        val = yield
        if val is None:
            break
        total += val
        yield total

class CountCalls:
    def __init__(self, func):
        self.func = func
        self.num_calls = 0
    def __call__(self, *args, **kwargs):
        self.num_calls += 1
        return self.func(*args, **kwargs)

